word-frequency:
words=input().split()
counts={}
for w in words:counts[w]=counts.get(w,0)+1
for w in sorted(counts):print(f"{w}:{counts[w]}")

merge-dicts:
a={'x':1,'y':2}
b={'y':3,'z':4}
c={**a,**b}
print(' '.join(f'{k}={c[k]}' for k in sorted(c)))

grade:
score=int(input())
if score>=90:print('A')
elif score>=80:print('B')
elif score>=70:print('C')
elif score>=60:print('D')
else:print('F')

fizzbuzz-one:
n=int(input())
if n%15==0:print('FizzBuzz')
elif n%3==0:print('Fizz')
elif n%5==0:print('Buzz')
else:print(n)

flatten-matrix:
